update country_flag_history set image_url = 'https://flagcdn.com/jp.svg' where id = 2173 and iso_code = 'jp';
update country_flag_history set label_fr = 'Empire du Japon puis Japon (1870-1999)', label_en = 'Empire of Japan, then Japan (1870–1999)', notes_fr = 'La proclamation du 27 février 1870 fait du Hinomaru le pavillon des navires marchands, avec un disque légèrement décentré vers la hampe ; la loi de 1999 le recentre et fixe ses proportions.', notes_en = 'The proclamation of 27 February 1870 made the Hinomaru the merchant flag, with a disc set slightly towards the hoist; the 1999 law centred it and fixed its proportions.' where id = 2418 and iso_code = 'jp';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('jp', '/flags/history/jp-1945.svg', '1945-09-02', '1952-04-28', 'Occupation alliée : pavillon des navires', 'Allied occupation: ship flag', 'Pendant l''occupation, l''usage du Hinomaru est restreint ; les navires japonais arborent un pavillon de signalisation modifié, à queue d''aronde.', 'During the occupation, use of the Hinomaru was restricted; Japanese ships flew a modified, swallow-tailed signal flag.');
